firecrawl interact -s 01a14c0b-f586-7774-ba60-aa1c22ef8d39 --node --timeout 60 -c '
const rows = await page.$$eval("tr", r=>r.map(x=>[...x.querySelectorAll("td,th")].map(c=>c.innerText.trim()).join("|")));
console.log(rows.length, rows.slice(0,6).join(" // "));
const inR=(p,s)=>{const [a,b]=s.split("---");const lo=+a,hi=b?+b:+a;return +p>=lo&&+p<=hi;};
for (const p of ["100","606","331","981","968"]) console.log(p, rows.filter(r=>{const [s]=r.split("|"); return /^\d{3}(---\d{3})?$/.test(s)&&inR(p,s)}));' 2>&1 | tail -8

